(function(){
'use strict';
const $=id=>document.getElementById(id),documents=DECLIC_COURSES,byId=new Map(documents.map(d=>[d.id,d]));let selected=null,subject=null,returnToQuiz=false,currentSource=null,pdfMode=true;
const searchable=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr');
function idsFor(quiz){return [...new Set([...(quiz.documents||[]),...quiz.cards.flatMap(c=>(c.sources||[]).map(s=>s.documentId))])].filter(id=>byId.has(id));}
function available(quiz){return idsFor(quiz).length>0;}
function make(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function renderText(){const host=$('course-pages');host.replaceChildren();const query=searchable($('course-search').value.trim());let visible=0;
 for(const page of selected.pages){if(query&&!searchable(page.text).includes(query))continue;visible++;const article=make('article','course-page');article.id='course-page-'+selected.id+'-'+page.number;article.appendChild(make('h2','','Page '+page.number));const body=make('div','course-page-text');const excerpt=currentSource?.documentId===selected.id&&currentSource?.page===page.number?currentSource.excerpt:null;
  const position=excerpt?page.text.indexOf(excerpt):-1;if(position>=0){body.append(document.createTextNode(page.text.slice(0,position)),make('mark','course-match',excerpt),document.createTextNode(page.text.slice(position+excerpt.length)));}else body.textContent=page.text;
  article.appendChild(body);host.appendChild(article);
 }
 $('course-no-results').classList.toggle('hidden',visible!==0);$('course-result-count').textContent=query?visible+' page(s) trouvée(s)':selected.pages.length+' pages · texte intégral';
}
function setDocument(id,page=1){selected=byId.get(id);if(!selected)return;$('course-document').value=id;$('course-page-select').replaceChildren();for(const p of selected.pages){const o=make('option','',String(p.number));o.value=String(p.number);$('course-page-select').appendChild(o);}$('course-page-select').value=String(Math.min(Math.max(page,1),selected.pages.length));$('course-title').textContent=selected.title;$('course-pdf-link').href=selected.url+'#page='+page;$('course-download').href=selected.url;$('course-download').textContent='Télécharger le PDF';renderText();setMode(pdfMode);}
function setMode(pdf){pdfMode=pdf;$('course-pages').classList.toggle('hidden',pdf);$('course-pdf').classList.toggle('hidden',!pdf);$('course-text-mode').setAttribute('aria-pressed',String(!pdf));$('course-pdf-mode').setAttribute('aria-pressed',String(pdf));if(pdf)$('course-pdf').src=selected.url+'#page='+$('course-page-select').value;else $('course-pdf').removeAttribute('src');}
function jump(page){$('course-page-select').value=String(page);$('course-pdf-link').href=selected.url+'#page='+page;if(pdfMode)$('course-pdf').src=selected.url+'#page='+page;else $( 'course-page-'+selected.id+'-'+page)?.scrollIntoView({behavior:'smooth',block:'start'});}
function open(quiz,source){subject=quiz;currentSource=source||null;returnToQuiz=!$('quiz-screen').classList.contains('hidden');$('library-screen').classList.add('hidden');$('quiz-screen').classList.add('hidden');$('course-screen').classList.remove('hidden');$('home-button').classList.remove('hidden');$('course-back').textContent=returnToQuiz?'← Revenir à la question':'← Mes quiz';$('course-search').value='';$('course-document').replaceChildren();const ids=idsFor(quiz);for(const id of ids){const d=byId.get(id),o=make('option','',d.title);o.value=id;$('course-document').appendChild(o);}const doc=source&&ids.includes(source.documentId)?source.documentId:ids[0];pdfMode=!source;setDocument(doc,source?.page||1);$('course-subject').textContent=quiz.title;document.title='Déclic · Cours de '+quiz.title;$('course-subject').focus();if(source)jump(source.page);else window.scrollTo({top:0,behavior:'smooth'});}
function renderSources(host,sources,quiz){host.replaceChildren();const valid=(sources||[]).filter(s=>byId.has(s.documentId)&&byId.get(s.documentId).pages.some(p=>p.number===s.page));host.classList.toggle('hidden',!valid.length);if(!valid.length)return;host.appendChild(make('h3','','La réponse dans ton cours'));for(const source of valid){const d=byId.get(source.documentId),section=make('div','source-reference');section.appendChild(make('p','source-location',d.title+' · page '+source.page));section.appendChild(make('blockquote','source-excerpt',source.excerpt));const button=make('button','btn ghost','Voir ce passage dans le cours');button.type='button';button.onclick=()=>open(quiz,source);section.appendChild(button);host.appendChild(section);}}
$('course-back').onclick=()=>{$('course-screen').classList.add('hidden');$('course-pdf').removeAttribute('src');if(returnToQuiz){$('quiz-screen').classList.remove('hidden');document.title='Déclic · '+subject.title;$('question').focus();}else DeclicLibrary.showLibrary();};$('course-document').addEventListener('change',()=>{currentSource=null;$('course-search').value='';setDocument($('course-document').value);});$('course-page-select').addEventListener('change',()=>jump(Number($('course-page-select').value)));$('course-search').addEventListener('input',()=>{setMode(false);renderText();});$('course-text-mode').onclick=()=>setMode(false);$('course-pdf-mode').onclick=()=>setMode(true);
globalThis.DeclicCourses={available,open,renderSources};
})();
